I = importlib
token_interface = [I.Func('transfer', args=('amount', 'to')), I.Func('mint',
    args=('amount', 'to')), I.Func('approve', args=('amount', 'to')), I.
    Func('transfer_from', args=('amount', 'to', 'main_account'))]
__supported_tokens = Hash(contract='con_lamden_link_v1', name=
    'supported_tokens')
__nonces = Hash(default_value=0, contract='con_lamden_link_v1', name='nonces')
__proofs = Hash(contract='con_lamden_link_v1', name='proofs')
__metadata = Hash(contract='con_lamden_link_v1', name='metadata')


def ____():
    __metadata['operator'] = ctx.caller


@__export('con_lamden_link_v1')
def change_metadata(key: str, value: Any):
    assert ctx.caller == __metadata['operator'
        ], 'Only operator can set metadata!'
    __metadata[key] = value


def __left_pad(s: str):
    while len(s) < 64:
        s = f'0{s}'
    if len(s) > 64:
        s = s[:64]
    return s


def __unpack_uint256(uint: str, decimals: int):
    i = int(uint, 16)
    reduced_i = i / 10 ** decimals
    return reduced_i


def __pack_amount(amount: float, decimals: int):
    i = int(amount * 10 ** decimals)
    h = hex(i)[2:]
    return __left_pad(h)


def __pack_eth_address(address: str):
    assert address.startswith('0x'), 'Invalid Ethereum prefix'
    a = address[2:]
    assert len(a) == 40, 'Invalid address length'
    int(a, 16)
    return __left_pad(a)


def __pack_int(i: int):
    i = int(i)
    h = hex(i)[2:]
    return __left_pad(h)


@__export('con_lamden_link_v1')
def mint(ethereum_contract: str, amount: str, lamden_wallet: str):
    assert ctx.caller == __metadata['operator'
        ], 'Only operator can call! Current caller is {}, operator should be {}'.format(
        ctx.caller, __metadata['operator'])
    assert __supported_tokens[ethereum_contract
        ] is not None, 'Invalid Ethereum Token!'
    decimals = __supported_tokens[ethereum_contract, 'decimals']
    assert decimals is not None, 'Unexpected decimal error'
    unpacked_amount = __unpack_uint256(amount, decimals)
    token = I.import_module(__supported_tokens[ethereum_contract])
    assert I.enforce_interface(token, token_interface
        ), 'Invalid token interface!'
    token.mint(amount=unpacked_amount, to=lamden_wallet)


@__export('con_lamden_link_v1')
def burn(ethereum_contract: str, ethereum_address: str, amount: float):
    assert __supported_tokens[ethereum_contract
        ] is not None, 'Invalid Ethereum Token!'
    token = I.import_module(__supported_tokens[ethereum_contract])
    assert I.enforce_interface(token, token_interface
        ), 'Invalid token interface!'
    token.transfer_from(amount=amount, to=ctx.this, main_account=ctx.caller)
    packed_token = __pack_eth_address(ethereum_contract)
    packed_amount = __pack_amount(amount, __supported_tokens[
        ethereum_contract, 'decimals'])
    packed_nonce = __pack_int(__nonces[ethereum_address] + 1)
    packed_address = __pack_eth_address(ethereum_address)
    __nonces[ethereum_address] += 1
    abi = packed_token + packed_amount + packed_nonce + packed_address
    return abi


@__export('con_lamden_link_v1')
def add_token(ethereum_contract: str, lamden_contract: str, decimals: int):
    assert __supported_tokens[ethereum_contract
        ] is None, 'Token already supported'
    assert ctx.caller == __metadata['operator'], 'Only operator can call!'
    token = I.import_module(lamden_contract)
    assert I.enforce_interface(token, token_interface
        ), 'Invalid token interface!'
    __supported_tokens[ethereum_contract] = lamden_contract
    __supported_tokens[ethereum_contract, 'decimals'] = decimals


@__export('con_lamden_link_v1')
def post_proof(hashed_abi: str, signed_abi: str):
    assert ctx.caller == __metadata['operator'], 'Only operator can call!'
    __proofs[hashed_abi] = signed_abi
